SELECT NumTstTakr, AvgScrMath 
FROM satscores 
WHERE cds = '1611190130609' AND FundingType = 'Directly Funded';

SELECT COUNT(DISTINCT driverId) 
FROM qualifying 
WHERE year = 1995 AND q1 > '2:00.000';

SELECT MAX(`RNP`) 
FROM Laboratory 
WHERE `DNA-II` < 1.5 AND `RNP` IS NOT NULL;

SELECT COUNT(*) 
FROM Patient 
WHERE SEX = 'Female' AND `First Date` BETWEEN '1998-01-01' AND '1998-12-31' AND Admission = 'Admitted';

SELECT 'F' AS `SEX`, COUNT(*) AS `COUNT` FROM Patient WHERE ID IN (SELECT ID FROM Laboratory) AND SEX = 'F'
UNION ALL
SELECT 'M' AS `SEX`, COUNT(*) AS `COUNT` FROM Patient WHERE ID IN (SELECT ID FROM Laboratory) AND SEX = 'M';
